    D3DPRESENT_PARAMETERS d3dpp = {};
    d3dpp.Windowed = TRUE;
    d3dpp.SwapEffect = D3DSWAPEFFECT_DISCARD;
    d3dpp.hDeviceWindow = CreateWindowA("STATIC", "", WS_POPUP | WS_VISIBLE, 100, 100, 800, 600, nullptr, nullptr, nullptr, nullptr);

    IDirect3DDevice9* pDevice;
    pD3D->CreateDevice(D3DADAPTER_DEFAULT, D3DDEVTYPE_HAL, d3dpp.hDeviceWindow, D3DCREATE_SOFTWARE_VERTEXPROCESSING, &d3dpp, &pDevice);

    // Example loop for rendering
