            player.base_address = currentPlayerBase;
            player.x = ReadMemory<float>(hProcess, currentPlayerBase + 0x34); // Example offset for X
            player.y = ReadMemory<float>(hProcess, currentPlayerBase + 0x38); // Example offset for Y
            player.z = ReadMemory<float>(hProcess, currentPlayerBase + 0x3C); // Example offset for Z
            players.push_back(player);
